import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

# EDA
try:
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    corr_matrix = df[num_cols].corr(method='pearson')
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['segment', 'region']
    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for seg in seg_cols:
        top_groups = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top_groups)]
        for metric in metric_cols:
            grp = sub.groupby(seg)[metric].mean()
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean',
                'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
            })
        cnt = sub.groupby(seg)['revenue'].count()
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'revenue',
            'aggregation': 'count',
            'results': [{'name': str(k), 'value': int(v)} for k, v in cnt.items()]
        })
    # Joint breakdown segment x region
    top_seg = df['segment'].value_counts().head(5).index
    top_reg = df['region'].value_counts().head(5).index
    sub2 = df[df['segment'].isin(top_seg) & df['region'].isin(top_reg)].copy()
    sub2['_key'] = sub2['segment'].astype(str) + '|' + sub2['region'].astype(str)
    for metric in ['revenue', 'units']:
        grp2 = sub2.groupby('_key')[metric].mean().nlargest(10)
        result['segments'].append({
            'segment_column': 'segment|region', 'metric_column': metric,
            'aggregation': 'mean',
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp2.items()]
        })
except Exception:
    pass

# ANOMALIES
try:
    import numpy as np
    anomaly_records = []
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min()) + 1
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged = df.loc[s_t[mask].index, col]
        orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(Q1 - 3*IQR)
        orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(Q3 + 3*IQR)
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx, val in flagged.items():
            tv = s_t[idx]
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['low','medium','high','critical'].index(x['severity']), reverse=True)
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

# TREND (7d rolling)
try:
    import numpy as np
    df['_date'] = pd.to_datetime(df['order_date'])
    daily = df.groupby('_date')[['revenue', 'units', 'discount', 'marketing_spend']].mean().sort_index()
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        rolled = daily[col].rolling(7).mean().dropna()
        if len(rolled) >= 2:
            first_val = float(rolled.iloc[0])
            last_val = float(rolled.iloc[-1])
            if first_val != 0:
                pct = round((last_val - first_val) / abs(first_val) * 100, 2)
            else:
                pct = 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col, 'period': '7d_rolling',
                'direction': direction, 'pct_change': pct, 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on revenue)
try:
    import numpy as np
    from scipy import stats as sp_stats
    df['_date'] = pd.to_datetime(df['order_date'])
    monthly = df.groupby(df['_date'].dt.to_period('M'))['revenue'].sum().sort_index()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, r, p, se = sp_stats.linregress(x, y)
        for step in [1, 2, 3]:
            pred_x = len(monthly) - 1 + step
            pred_val = float(intercept + slope * pred_x)
            last_period = monthly.index[-1]
            future_period = (last_period + step).strftime('%Y-%m')
            result['forecast_points'].append({'period': future_period, 'value': round(pred_val, 2)})
        r_val = round(float(r), 4)
        p_val = round(float(p), 4)
        result['statistical_tests'].append({
            'test_name': 'Linear trend (revenue monthly)',
            'statistic': round(float(slope), 4),
            'p_value': p_val,
            'interpretation': f'Monthly revenue linear trend slope={round(float(slope),4)}, r={r_val}, p={p_val}; {"significant" if p_val < 0.05 else "no significant"} linear trend'
        })
except Exception:
    pass

result['assumptions'] = [
    'discount column treated as a rate (0-1); 7d rolling trend uses daily means for rates',
    'Anomaly detection uses log1p transform for columns with abs(skew)>2',
    'Forecasting uses OLS linear regression on monthly revenue totals',
    'Segmentation limited to top 10 groups by count; customer_email excluded (high cardinality)',
    'Notes column contains embedded instruction-like text in data; ignored per policy'
]

