try:
    import numpy as np
    from scipy import stats as sp_stats
    df['_date'] = pd.to_datetime(df['order_date'])
    monthly = df.groupby(df['_date'].dt.to_period('M'))['revenue'].sum().sort_index()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, r, p, se = sp_stats.linregress(x, y)
        for step in [1, 2, 3]:
            pred_x = len(monthly) - 1 + step
            pred_val = float(intercept + slope * pred_x)
            last_period = monthly.index[-1]
            future_period = (last_period + step).strftime('%Y-%m')
            result['forecast_points'].append({'period': future_period, 'value': round(pred_val, 2)})
        r_val = round(float(r), 4)
        p_val = round(float(p), 4)
        result['statistical_tests'].append({
            'test_name': 'Linear trend (revenue monthly)',
            'statistic': round(float(slope), 4),
            'p_value': p_val,
            'interpretation': f'Monthly revenue linear trend slope={round(float(slope),4)}, r={r_val}, p={p_val}; {"significant" if p_val < 0.05 else "no significant"} linear trend'
        })
