# ANOMALIES
try:
    import numpy as np
    anomaly_records = []
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min()) + 1
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s) > 0.05:
