# ANOMALIES
try:
    import numpy as np
    anomaly_records = []
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min()) + 1
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged = df.loc[s_t[mask].index, col]
        orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(Q1 - 3*IQR)
        orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(Q3 + 3*IQR)
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx, val in flagged.items():
            tv = s_t[idx]
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['low','medium','high','critical'].index(x['severity']), reverse=True)
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

