import numpy as np
from scipy import stats

numeric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
segment_cols = ['segment', 'region']
date_col = 'order_date'

# EDA
try:
    eda = {}
    for col in numeric_cols:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# CORRELATIONS
try:
    corrs = {}
    num_df = df[numeric_cols].dropna()
    cols = numeric_cols
    for i in range(len(cols)):
        for j in range(i+1, len(cols)):
            c1, c2 = cols[i], cols[j]
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                corrs[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corrs
except Exception:
    pass

# SEGMENTATION
try:
    segs = []
    for seg_col in segment_cols:
        top10 = df[seg_col].value_counts().head(10).index.tolist()
        sub = df[df[seg_col].isin(top10)]
        for metric in numeric_cols:
            for agg, agg_name in [('mean', 'mean'), ('sum', 'sum')]:
                grp = sub.groupby(seg_col)[metric].agg(agg)
                segs.append({
                    "segment_column": seg_col,
                    "metric_column": metric,
                    "aggregation": agg_name,
                    "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
                })
    # Joint breakdown segment x region
    top_seg = df['segment'].value_counts().head(5).index.tolist()
    top_reg = df['region'].value_counts().head(5).index.tolist()
    sub2 = df[df['segment'].isin(top_seg) & df['region'].isin(top_reg)].copy()
    sub2['_joint'] = sub2['segment'].astype(str) + '|' + sub2['region'].astype(str)
    for metric in ['revenue', 'units']:
        grp2 = sub2.groupby('_joint')[metric].mean()
        segs.append({
            "segment_column": "segment|region",
            "metric_column": metric,
            "aggregation": "mean",
            "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp2.items()]
        })
    result['segments'] = segs
except Exception:
    pass

# ANOMALIES
try:
    anomalies = []
    total_cap = 25
    skip_cols = set()
    for col in numeric_cols:
        s = df[col].dropna()
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3*iqr, q3 + 3*iqr
        flagged = s_t[(s_t < lo_t) | (s_t > hi_t)]
        frac = len(flagged) / len(s_t) if len(s_t) > 0 else 0
        if frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"heavy-tailed distribution",
                "severity": "low",
                "explanation": f"Column {col} is heavy-tailed; extreme-value flagging suppressed."
            })
            skip_cols.add(col)
            continue
        # original units boundaries
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = float(lo_t), float(hi_t)
        exp_range = f"[{lo_orig:.4g}, {hi_orig:.4g}]"
        lo5_t, hi5_t = q1 - 5*iqr, q3 + 5*iqr
        lo4_t, hi4_t = q1 - 4*iqr, q3 + 4*iqr
        for idx in flagged.index:
            if len(anomalies) >= total_cap:
                break
            raw_val = float(df.loc[idx, col])
            tv = float(s_t.loc[idx])
            if tv > hi5_t or tv < lo5_t:
                sev = "critical"
            elif tv > hi4_t or tv < lo4_t:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": raw_val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"Value {raw_val} in column {col} lies outside expected range {exp_range}."
            })
        if len(anomalies) >= total_cap:
            break
    result['anomalies'] = anomalies
except Exception:
    pass

# TRENDS (non-MoM — rolling 7d on revenue)
try:
    df['_date'] = df[date_col].astype('datetime64[ns]')
    daily = df.groupby('_date')['revenue'].sum().sort_index()
    rolling7 = daily.rolling(7).mean().dropna()
    if len(rolling7) >= 2:
        first7 = float(rolling7.iloc[0])
        last7 = float(rolling7.iloc[-1])
        pct = round((last7 - first7) / first7 * 100, 4) if first7 != 0 else 0.0
        direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
        result['trends'].append({
            "column": "revenue", "period": "7d_rolling",
            "direction": direction, "pct_change": pct, "segment": None
        })
    # YoY not applicable (single year); MoM handled externally
except Exception:
    pass

# FORECASTING (simple linear extrapolation on monthly revenue)
try:
    df['_date'] = df[date_col].astype('datetime64[ns]')
    monthly = df.groupby(df['_date'].dt.to_period('M'))['revenue'].sum().sort_index()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        fps = []
        last_period = monthly.index[-1]
        for step in range(1, 4):
            pred_val = float(intercept + slope * (len(monthly) - 1 + step))
            next_p = last_period + step
            fps.append({"period": str(next_p), "value": round(pred_val, 4)})
        result['forecast_points'] = fps
except Exception:
    pass

