try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in num_cols:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0
        Q1, Q3 = vals.quantile(0.25), vals.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3 * IQR, Q3 + 3 * IQR
        lo4, hi4 = Q1 - 4 * IQR, Q3 + 4 * IQR
        lo5, hi5 = Q1 - 5 * IQR, Q3 + 5 * IQR
        mask = (vals < lo3) | (vals > hi3)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.3g}, {float(s.quantile(0.75)):.3g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value rule would flag >{frac*100:.1f}% of rows, so no individual anomalies are reported.'
            })
            continue
        flagged_idx = vals[mask].index
        for idx in flagged_idx:
            orig_val = float(df.loc[idx, col])
            tv = vals[idx]
            if abs(skew) > 2:
                orig_lo = float(np.expm1(lo3) - shift)
                orig_hi = float(np.expm1(hi3) - shift)
            else:
                orig_lo, orig_hi = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3), float(hi3)
            exp_range = f'[{orig_lo:.3g}, {orig_hi:.3g}]'
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}.'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception:
    pass

