    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly_rev = df.groupby('_ym')['revenue'].mean().reset_index()
    monthly_rev['_t'] = range(len(monthly_rev))
    if len(monthly_rev) >= 3:
        from scipy import stats as sp_stats
        slope, intercept, r, p, se = sp_stats.linregress(monthly_rev['_t'], monthly_rev['revenue'])
        last_t = monthly_rev['_t'].max()
        fps = []
        for ahead in [1, 2, 3]:
            t_val = last_t + ahead
            pred = float(intercept + slope * t_val)
            period_label = str((monthly_rev['_ym'].iloc[-1] + ahead))
            fps.append({'period': period_label, 'value': round(pred, 4)})
        result['forecast_points'].extend(fps)
        r_val = round(float(r), 4)
        p_val = round(float(p), 6)
        result['statistical_tests'].append({
            'test_name': 'Linear trend (revenue ~ month index)',
            'statistic': r_val, 'p_value': p_val,
            'interpretation': f'r={r_val}, p={p_val}; ' + ('significant linear trend in revenue over time.' if p_val < 0.05 else 'no significant linear trend in revenue over time.')
        })
