try:
    import numpy as np
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags >{frac*100:.1f}% of values as extreme; treated as heavy-tailed, not anomalies'
            })
            continue
        flagged = s[mask.values]
        for idx, val in flagged.items():
            lv = np.log1p(val + shift) if abs(skew) > 2 else val
            if abs(skew) > 2:
                orig_lo = float(np.expm1(lo3) - shift)
                orig_hi = float(np.expm1(hi3) - shift)
            else:
                orig_lo, orig_hi = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3), float(hi3)
            if lv > hi5 or lv < lo5:
                sev = 'critical'
            elif lv > hi4 or lv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            er = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': er, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {er}'
            })
        if len(anomaly_records) >= 25:
            break
    result['anomalies'].extend(anomaly_records[:25])
except Exception:
    pass

