import numpy as np
from scipy import stats

# EDA
try:
    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_df = df[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['segment', 'region']
    for seg in seg_cols:
        for metric in metric_cols:
            grp = df.groupby(seg)[metric].mean().nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean',
                'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
            })
    for seg in seg_cols:
        grp = df.groupby(seg)['order_id'].count().nlargest(10)
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'order_id',
            'aggregation': 'count',
            'results': [{'name': str(k), 'value': int(v)} for k, v in grp.items()]
        })
    # Two-column breakdown segment|region
    if len(seg_cols) >= 2:
        for metric in ['revenue', 'units']:
            grp = df.groupby(['segment', 'region'])[metric].mean()
            top = grp.nlargest(10)
            result['segments'].append({
                'segment_column': 'segment|region', 'metric_column': metric,
                'aggregation': 'mean',
                'results': [{'name': f'{k[0]}|{k[1]}', 'value': round(float(v), 4)} for k, v in top.items()]
            })
except Exception:
    pass

# ANOMALIES
try:
    anomaly_records = []
    anom_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in anom_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0.0
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_work = np.log1p(s + shift)
        else:
            s_work = s.copy()
        q1, q3 = float(s_work.quantile(0.25)), float(s_work.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_work < lo3) | (s_work > hi3)
        frac = mask.sum() / len(s_work)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged_idx = s_work[mask].index
        orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
        orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx in flagged_idx:
            val = float(df.loc[idx, col])
            w = float(s_work.loc[idx])
            if w > hi5 or w < lo5:
                sev = 'critical'
            elif w > hi4 or w < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val:.4g} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception:
    pass

# TRENDS (non-MoM — rolling 7d on revenue)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    daily = df.groupby('order_date')['revenue'].sum().sort_index()
    roll = daily.rolling(7).mean().dropna()
    if len(roll) >= 2:
        first_val, last_val = float(roll.iloc[0]), float(roll.iloc[-1])
        pct = round((last_val - first_val) / first_val * 100, 4) if first_val != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': 'revenue', 'period': '7d_rolling',
            'direction': direction, 'pct_change': pct, 'segment': None
        })
    for metric in ['units', 'discount', 'marketing_spend']:
        dm = df.groupby('order_date')[metric].mean().sort_index()
        roll_m = dm.rolling(7).mean().dropna()
        if len(roll_m) >= 2:
            fv, lv = float(roll_m.iloc[0]), float(roll_m.iloc[-1])
            pct_m = round((lv - fv) / fv * 100, 4) if fv != 0 else 0.0
            dir_m = 'up' if pct_m > 1 else ('down' if pct_m < -1 else 'flat')
            result['trends'].append({
                'column': metric, 'period': '7d_rolling',
                'direction': dir_m, 'pct_change': pct_m, 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on monthly revenue)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['ym'] = df['order_date'].dt.to_period('M')
    monthly = df.groupby('ym')['revenue'].sum().sort_index()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        for step in [1, 2, 3]:
            next_x = len(monthly) - 1 + step
            next_period = str(monthly.index[-1] + step)
            pred = round(float(intercept + slope * next_x), 4)
            result['forecast_points'].append({'period': next_period, 'value': pred})
except Exception:
    pass

# ASSUMPTIONS
result['assumptions'] = [
    'Pearson r used for correlations; linear association only, not causation.',
    'Anomaly detection uses Q1-3xIQR / Q3+3xIQR extreme boundaries; log1p applied when |skew|>2.',
    'Forecasting uses OLS linear regression on monthly revenue totals; assumes linear trend.',
    '7-day rolling trend direction threshold is ±1% change from first to last window.',
    'customer_email excluded from segmentation due to high cardinality (PII masked).'
]

